            cut_out_LNG = 1;
            cut_in_DG1 = 0;
            cut_out_DG1 = 1;
            cut_in_DG2 = 0;
            cut_out_DG2 = 1;
            cut_in_loads = 1;
            cut_out_loads = 0;
        }
    }

    state BatteryDischarge {
        enter {
            Plng_req = 0.0;
            Pd1_req = 0.0;
            Pd2_req = 0.0;
            Pbat_dis = PL - Ppv - Pw;
            Pbat_ch = 0.0;
            spare_power = 0.0;
            cut_in_LNG = 0;
            cut_out_LNG = 1;
            cut_in_DG1 = 0;
            cut_out_DG1 = 1;
            cut_in_DG2 = 0;
            cut_out_DG2 = 1;
            cut_in_loads = 1;
            cut_out_loads = 0;
        }
    }

    state LngWithBattery {
        enter {
            Plng_req = PL - Ppv - Pw - Pbat_Pmax;
