    state LngLowSocCharge {
        enter {
            Plng_req = PL - Ppv - Pw + Pgmax / 5;
            Pd1_req = 0.0;
            Pd2_req = 0.0;
            Pbat_dis = 0.0;
            Pbat_ch = Pgmax / 5;
            spare_power = 0.0;
            cut_in_LNG = 1;
            cut_out_LNG = 0;
            cut_in_DG1 = 0;
            cut_out_DG1 = 1;
            cut_in_DG2 = 0;
            cut_out_DG2 = 1;
            cut_in_loads = 1;
            cut_out_loads = 0;
        }
    }

    state Dg1WithBattery {
        enter {
            Plng_req = eng3_Pmax;
            Pd1_req = PL - Ppv - Pw - Pbat_Pmax - eng3_Pmax;
            Pd2_req = 0.0;
            Pbat_dis = Pbat_Pmax;
            Pbat_ch = 0.0;
            spare_power = 0.0;
            cut_in_LNG = 1;
            cut_out_LNG = 0;
            cut_in_DG1 = 1;
            cut_out_DG1 = 0;
            cut_in_DG2 = 0;
            cut_out_DG2 = 1;
            cut_in_loads = 1;
            cut_out_loads = 0;
        }
    }

    state Dg1LowSocCharge {
        enter {
            Plng_req = eng3_Pmax;
            Pd1_req = PL - Ppv - Pw + Pd1max / 10 - eng3_Pmax;
            Pd2_req = 0.0;
            Pbat_dis = 0.0;
            Pbat_ch = Pd1max / 10;
            spare_power = 0.0;
