            cut_out_LNG = 0;
            cut_in_DG1 = 1;
            cut_out_DG1 = 0;
            cut_in_DG2 = 0;
            cut_out_DG2 = 1;
            cut_in_loads = 1;
            cut_out_loads = 0;
        }
    }

    state Dg2WithBattery {
        enter {
            Plng_req = eng3_Pmax;
            Pd1_req = Pd1max;
            Pd2_req = PL - Ppv - Pw - Pbat_Pmax - eng3_Pmax - Pd1max;
            Pbat_dis = Pbat_Pmax;
            Pbat_ch = 0.0;
            spare_power = 0.0;
            cut_in_LNG = 1;
            cut_out_LNG = 0;
            cut_in_DG1 = 1;
            cut_out_DG1 = 0;
            cut_in_DG2 = 1;
            cut_out_DG2 = 0;
            cut_in_loads = 1;
            cut_out_loads = 0;
        }
    }

    state Dg2LowSocCharge {
        enter {
            Plng_req = eng3_Pmax;
            Pd1_req = Pd1max;
            Pd2_req = PL - Ppv - Pw + Pd1max / 10 - eng3_Pmax - Pd1max;
            Pbat_dis = 0.0;
            Pbat_ch = Pd1max / 10;
            spare_power = 0.0;
            cut_in_LNG = 1;
            cut_out_LNG = 0;
            cut_in_DG1 = 1;
            cut_out_DG1 = 0;
            cut_in_DG2 = 1;
            cut_out_DG2 = 0;
            cut_in_loads = 1;
            cut_out_loads = 0;
        }
    }

    state OverloadCompletionIllegal {
        enter {
            Plng_req = eng3_Pmax;
            Pd1_req = Pd1max;
            Pd2_req = Pd2max;
            Pbat_dis = PL - Ppv - Pw - eng3_Pmax - Pd1max - Pd2max;
            Pbat_ch = 0.0;
            spare_power = 0.0;
            cut_in_LNG = 1;
            cut_out_LNG = 0;
            cut_in_DG1 = 1;
            cut_out_DG1 = 0;
            cut_in_DG2 = 1;
            cut_out_DG2 = 0;
            cut_in_loads = 1;
            cut_out_loads = 0;
        }
    }
}

